export const IMPORT_INPUT = "// package comment\npackage main\n\nimport (\n\t\"fmt\"\n\t\"math\"\n\t\"log\"\n\t\"errors\"\n\t\"io\"\n)\n\nimport (\n\t\"fmt\"\n\n\t\"math\"\n\n\t\"log\"\n\n\t\"errors\"\n\n\t\"io\"\n)\n\n// We reset the line numbering to test that\n// the formatting works independent of line directives\n//line :19\n\nimport (\n\t\"fmt\"\n\t\"math\"\n\t\"log\"\n\t\"errors\"\n\t\"io\"\n\n\t\"fmt\"\n\n\t\"math\"\n\n\t\"log\"\n\n\t\"errors\"\n\n\t\"io\"\n)\n\nimport (\n\t// a block with comments\n\t\"fmt\" // for Printf\n\t\"math\"\n\t\"log\" // for Fatal\n\t\"errors\"\n\t\"io\" // for Reader\n)\n\nimport (\n\t\"fmt\" // for Printf\n\n\t\"math\"\n\n\t\"log\" // for Fatal\n\n\t\"errors\"\n\n\t\"io\" // for Reader\n)\n\nimport (\n\t// for Printf\n\t\"fmt\"\n\n\t\"math\"\n\n\t// for Fatal\n\t\"log\"\n\n\t\"errors\"\n\n\t// for Reader\n\t\"io\"\n)\n\nimport (\n\t\"fmt\" // for Printf\n\t\"math\"\n\t\"log\" // for Fatal\n\t\"errors\"\n\t\"io\" // for Reader\n\n\t\"fmt\" // for Printf\n\n\t\"math\"\n\n\t\"log\" // for Fatal\n\n\t\"errors\"\n\n\t\"io\" // for Reader\n)\n\nimport (\n\t\"fmt\" // for Printf\n\n\t\"math\"\n\t\"log\" // for Fatal\n\t\"errors\"\n\t\"io\" // for Reader\n\n\t\"fmt\" // for Printf\n\t\"math\"\n\t\"log\" // for Fatal\n\t\"errors\"\n\t\"io\" // for Reader\n)\n\n// Test deduping and extended sorting\nimport (\n\t\"B\" // B\n\ta \"A\" // aA\n\tb \"A\" // bA2\n\tb \"A\" // bA1\n\t. \"B\" // .B\n\t. \"B\"\n\t\"C\"\n\t\"C\"\n\t\"C\"\n\ta \"D\" // aD\n\t\"B\"\n\t_ \"B\" // _b\n)\n\nimport (\n\t\"dedup_by_group\"\n\t\"dedup_by_group\"\n\n\t\"dedup_by_group\"\n)\n\nimport (\n\t/* comment */ io1 \"io\"\n\t\"fmt\" // for Printf\n\t/* comment */ \"log\"\n\t/* comment */ io2 \"io\"\n)\n\nimport (\n\t/* comment */ io2 \"io\" // hello\n\t/* comment */ io1 \"io\"\n\t\"math\" /* right side */\n\t\"fmt\"\n\t// end\n)\n\nimport (\n\t/* comment */ io1 \"io\" /* before */ // after\n\t\"fmt\"\n\t\"errors\" // for New\n\tio2 \"io\" // another\n\t// end\n)\n\nimport (\n\t/* left */ \"fmt\" /* right */\n\t\"errors\" // for New\n\t/* left */ \"math\" /* right */\n\t\"log\" // for Fatal\n)\n\nimport /* why */ /* comment here? */ (\n\t/* comment */ \"fmt\"\n\t\"math\"\n)\n\n// Reset it again\n//line :100\n\n// Dedup with different import styles\nimport (\n\t\"path\"\n\t. \"path\"\n\t_ \"path\"\n\t\"path\"\n\tpathpkg \"path\"\n)\n\n/* comment */\nimport (\n\t\"math\" // for Abs\n\t\"fmt\"\n\t// This is a new run\n\t\"errors\"\n\t\"fmt\"\n\t\"errors\"\n)\n\n// End an import declaration in the same line\n// as the last import. See golang.org/issue/33538.\n// Note: Must be the last (or 2nd last) line of the file.\nimport(\"fmt\"\n\"math\")";

